insert into public.advice_guides (slug, title, summary, category, content, featured_rank, related_slugs, author_name, reviewed_on, published_at)
values (
  'cv-checklist-before-you-apply', 'A CV checklist to run before every application', 'Eight quick checks that catch the problems recruiters notice first — before you press send.', 'cv',
  $json$[{"type":"paragraph","text":"A CV is read quickly, usually by someone deciding whether to keep reading. Most rejections at this stage are not about ability; they are about the CV making the reader work. This checklist takes about five minutes and is worth doing every time, because the right CV for one role is rarely the right CV for the next."},{"type":"heading","level":2,"id":"match-the-role","text":"Match it to the role"},{"type":"paragraph","text":"Read the advert and pick out the three or four things it asks for most clearly. Then check that each appears, in plain words, near the top of your CV or in your most recent role. Use the employer's own wording where it is honest to do so: if they say \"stakeholder management\" and you say \"working with people\", the match is harder to see."},{"type":"heading","level":2,"id":"lead-with-evidence","text":"Lead with evidence, not adjectives"},{"type":"paragraph","text":"\"Motivated team player\" tells the reader nothing they can check. \"Led a team of four to cut order processing time by a third\" does. For each role, prefer bullets that say what you did and what changed because of it, with numbers where you genuinely have them."},{"type":"heading","level":2,"id":"the-checks","text":"The checks"},{"type":"list","items":["Your name, email and phone number are at the top and spelled correctly.","A short profile at the start says who you are and what you are aiming for, in your own words.","Roles are in reverse order, most recent first, with dates that add up.","Every bullet starts with an action and finishes with a result or a reason it mattered.","Skills that appear in the advert appear on your CV — only the ones you can talk about at interview.","Formatting is plain: one column, standard headings, a readable font, no text hidden in images.","It is the length the role calls for — usually one or two pages — with the strongest material first.","There are no spelling mistakes; read it aloud, and ask someone else to read it too."]},{"type":"heading","level":2,"id":"save-a-version","text":"Save a version for each application"},{"type":"paragraph","text":"Keep a master CV with everything, and make a copy for each application that you adjust. Name the copies so you can find the one you sent when an interview invitation arrives weeks later. If you use JobPilot, each application can point at the exact CV version you submitted."}]$json$::jsonb,
  1, array['how-applicant-tracking-systems-read-your-cv', 'keep-track-of-every-application']::text[], 'JobPilot AI editorial team', '2026-08-28', '2026-08-28T09:00:00.000Z'
)
on conflict (slug) do nothing;

insert into public.advice_guides (slug, title, summary, category, content, featured_rank, related_slugs, author_name, reviewed_on, published_at)
values (
  'how-applicant-tracking-systems-read-your-cv', 'How applicant tracking systems read your CV', 'What an ATS does with your CV, what it doesn''t, and the formatting habits that avoid trouble.', 'ats',
  $json$[{"type":"paragraph","text":"Most employers use an applicant tracking system (ATS) to collect applications. It stores your CV, extracts the text into fields, and lets recruiters search and filter. What it does after that varies by employer and by system, so be wary of anyone who claims to know exactly how \"the ATS\" scores you — there is no single one."},{"type":"heading","level":2,"id":"what-it-does","text":"What an ATS usually does"},{"type":"list","items":["Reads your CV file and turns it into text, then tries to sort that text into sections such as experience, education and skills.","Stores it so recruiters can search by keyword, job title, location or date.","Sometimes ranks or filters applicants against criteria the employer set — and often simply presents them in a list for a person to review."]},{"type":"heading","level":2,"id":"why-format-matters","text":"Why formatting still matters"},{"type":"paragraph","text":"If the system cannot extract your text cleanly, a recruiter searching for a skill you have may never see you. Layouts that tend to cause problems are the ones that hide text from a parser: content inside images, text boxes, headers and footers, multi-column designs and unusual symbols used as bullets."},{"type":"heading","level":2,"id":"safe-habits","text":"Habits that keep your CV readable by both people and software"},{"type":"list","items":["Use a single column with standard headings such as Experience, Education and Skills.","Put your contact details in the body of the page, not in the header or footer.","Submit the file type the employer asks for; if there is a choice, a text-based PDF or Word document is the safe option.","Spell out terms at least once — \"search engine optimisation (SEO)\" — because people search for both forms."]},{"type":"heading","level":2,"id":"keywords","text":"Keywords are for people too"},{"type":"paragraph","text":"Matching the employer's wording helps a keyword search and helps the person reading. But repeating a term that does not describe what you did only makes the CV harder to trust. Include the words the advert uses where they truthfully apply, in the context of real work, rather than adding a block of them at the bottom."},{"type":"quote","text":"The goal is not to beat a system. It is to make sure the people who do read your application can find, quickly, why you fit."}]$json$::jsonb,
  2, array['cv-checklist-before-you-apply', 'keep-track-of-every-application']::text[], 'JobPilot AI editorial team', '2026-08-31', '2026-08-31T09:00:00.000Z'
)
on conflict (slug) do nothing;

insert into public.advice_guides (slug, title, summary, category, content, featured_rank, related_slugs, author_name, reviewed_on, published_at)
values (
  'prepare-for-a-competency-interview', 'Preparing for a competency interview with the STAR method', 'How to build a small bank of real examples, structure each one, and practise saying it out loud.', 'interviews',
  $json$[{"type":"paragraph","text":"Competency interviews ask for examples of how you have behaved before: \"Tell me about a time you worked under pressure.\" The employer is using your past as evidence. The way to prepare is not to memorise answers but to collect a handful of true stories and practise telling them clearly."},{"type":"heading","level":2,"id":"build-your-examples","text":"Build a bank of examples"},{"type":"paragraph","text":"Pick five or six experiences from work, study, volunteering or projects. Choose ones where you had a real part and something changed. Then note which skills each could illustrate — most good examples can answer several different questions."},{"type":"heading","level":2,"id":"use-star","text":"Structure each one with STAR"},{"type":"list","items":["Situation: the context, in a sentence or two.","Task: what you were responsible for.","Action: what you did — this is the longest part, and it should be about you, not \"we\".","Result: what happened, ideally something measurable, and what you learned."]},{"type":"heading","level":2,"id":"common-mistakes","text":"Common mistakes"},{"type":"list","items":["Spending most of the answer on the situation and rushing the action.","Saying \"we\" throughout, so the interviewer cannot tell what you did.","Ending without a result, or with a result that doesn't connect to the question.","Reusing the same example for every question."]},{"type":"heading","level":2,"id":"practise-aloud","text":"Practise out loud"},{"type":"paragraph","text":"An answer that reads well often sounds rambling when spoken. Say each example aloud, aim for around two minutes, and record it if you can. Ask a friend to interrupt with a follow-up, because interviewers will. JobPilot's Interview Coach gives you scored practice with follow-up questions, but a friend and a timer work too."}]$json$::jsonb,
  null, array['the-main-graduate-assessments-explained', 'choosing-between-job-offers']::text[], 'JobPilot AI editorial team', '2026-09-03', '2026-09-03T09:00:00.000Z'
)
on conflict (slug) do nothing;

insert into public.advice_guides (slug, title, summary, category, content, featured_rank, related_slugs, author_name, reviewed_on, published_at)
values (
  'keep-track-of-every-application', 'How to keep track of every application', 'A simple system for deadlines, versions and follow-ups so nothing slips while you apply widely.', 'applications',
  $json$[{"type":"paragraph","text":"Once you are applying to more than a few roles, memory stops being enough. Deadlines pass, you forget which CV you sent, and an interview invitation arrives for a role you barely remember. A simple tracking habit prevents most of this."},{"type":"heading","level":2,"id":"what-to-record","text":"What to record for each application"},{"type":"list","items":["The employer, the role and a link to the advert (adverts get taken down).","The closing date, and whether the employer reviews applications as they arrive.","The exact CV and cover letter you sent.","Where you are: not yet applied, applied, interview, offer, or closed.","The date you should follow up if you hear nothing."]},{"type":"heading","level":2,"id":"deadlines-first","text":"Work back from deadlines"},{"type":"paragraph","text":"List applications by closing date, not by how interesting they are. Where an employer reviews on a rolling basis, apply earlier: a role can close once enough good applications have arrived. Give yourself a buffer for the parts that take longest, such as online tests."},{"type":"heading","level":2,"id":"follow-up","text":"Follow up sensibly"},{"type":"paragraph","text":"If an employer told you when to expect an answer, wait until that date has passed. Then a short, polite message asking about the timeline is fine. If they did not say, a week or two is a reasonable gap. Keep it brief and note the date you sent it."},{"type":"heading","level":2,"id":"review-weekly","text":"Review weekly"},{"type":"paragraph","text":"Once a week, look at the whole list: what closes soon, what needs a follow-up, and which applications are quietly finished. A spreadsheet is enough; JobPilot's tracker adds reminders and keeps the CV version you sent."}]$json$::jsonb,
  null, array['cv-checklist-before-you-apply', 'how-to-read-a-graduate-scheme-listing']::text[], 'JobPilot AI editorial team', '2026-09-06', '2026-09-06T09:00:00.000Z'
)
on conflict (slug) do nothing;

insert into public.advice_guides (slug, title, summary, category, content, featured_rank, related_slugs, author_name, reviewed_on, published_at)
values (
  'how-to-read-a-graduate-scheme-listing', 'How to read a graduate scheme listing', 'Deadlines, study stage, rolling applications and assessments — what each detail means for when and how you apply.', 'graduate_schemes',
  $json$[{"type":"paragraph","text":"Graduate scheme listings pack a lot into a few lines, and small details change what you should do and when. This guide explains the ones that matter most."},{"type":"heading","level":2,"id":"deadlines-and-rolling","text":"Deadlines and rolling applications"},{"type":"paragraph","text":"A closing date is the last day to apply. Some schemes instead review applications \"on a rolling basis\": they assess candidates as they arrive and can fill places, or close, before any stated date. If a scheme is rolling, apply early. If no deadline is published at all, treat that as unknown rather than open-ended and check the employer's own page."},{"type":"heading","level":2,"id":"who-it-is-for","text":"Who a scheme is open to"},{"type":"paragraph","text":"Listings usually say which stage you need to be at — for example students in their final year, recent graduates, or postgraduates. Read this before investing time in an application; it is often a firm requirement, not a preference. The degree subject, classification and eligibility to work in the UK are separate requirements, so check each one."},{"type":"heading","level":2,"id":"selection-process","text":"The selection process"},{"type":"paragraph","text":"Many schemes use several stages: an online application, one or more online tests, a video or phone interview, and sometimes an assessment centre. Knowing the stages in advance lets you plan practice time. Where the process is not published, do not assume — ask, or look for what previous applicants have described in the employer's own materials."},{"type":"heading","level":2,"id":"sponsorship","text":"Visa sponsorship"},{"type":"paragraph","text":"If you need permission to work in the UK, look for what the employer says about sponsorship for that scheme specifically. It can differ between schemes and locations, and it is not a guarantee of an offer. Always confirm on the employer's own page and, for licences, on the official register."},{"type":"heading","level":2,"id":"check-the-source","text":"Check the source"},{"type":"paragraph","text":"Dates and requirements change. Whatever you read here or anywhere else, confirm the closing date and requirements on the employer's own page before you apply."}]$json$::jsonb,
  3, array['the-main-graduate-assessments-explained', 'sponsorship-basics-what-a-licence-means']::text[], 'JobPilot AI editorial team', '2026-09-09', '2026-09-09T09:00:00.000Z'
)
on conflict (slug) do nothing;

insert into public.advice_guides (slug, title, summary, category, content, featured_rank, related_slugs, author_name, reviewed_on, published_at)
values (
  'sponsorship-basics-what-a-licence-means', 'Sponsorship basics: what a sponsor licence does and doesn''t mean', 'A plain explanation of sponsor licences and the official register, and how to use them in a job search. Not immigration advice.', 'visa_sponsorship',
  $json$[{"type":"paragraph","text":"This guide is general information, not immigration advice. Visa rules change, and your circumstances matter: always check the current rules on the official government website, and speak to a qualified adviser about your own situation."},{"type":"heading","level":2,"id":"what-a-licence-is","text":"What a sponsor licence is"},{"type":"paragraph","text":"To employ someone who needs permission to work in the UK through certain routes, an employer generally needs to hold a sponsor licence from the Home Office. The Home Office publishes a register of licensed sponsors, which is public. If an employer is not on it, they may not be able to sponsor you on those routes."},{"type":"heading","level":2,"id":"what-it-does-not-mean","text":"What it does not mean"},{"type":"list","items":["Being on the register does not mean an employer will sponsor you for a particular job — that is their decision for each role.","It does not guarantee you an offer, or that your role would meet the requirements of any visa route.","It does not tell you which routes an employer is licensed for in every case."]},{"type":"heading","level":2,"id":"how-to-use-it","text":"How to use the register in a search"},{"type":"paragraph","text":"Use it to build a list of employers who are able to sponsor, then look at what each says about sponsorship in its job adverts and graduate pages. Where an advert says sponsorship is available, that is more reliable than the register alone. Where it says nothing, you can ask the employer politely before applying."},{"type":"heading","level":2,"id":"when-to-ask","text":"When to raise it"},{"type":"paragraph","text":"You can usually check the employer's stated position before you apply. If you do not see one, asking early saves you time. Employers generally expect the question, and a short, factual email is enough."},{"type":"heading","level":2,"id":"keep-checking","text":"Keep checking the official source"},{"type":"paragraph","text":"Requirements such as salary levels, skill levels and fees are set by the government and are updated. Always use the official pages for current figures rather than relying on any guide, including this one."}]$json$::jsonb,
  null, array['how-to-read-a-graduate-scheme-listing', 'choosing-between-job-offers']::text[], 'JobPilot AI editorial team', '2026-09-12', '2026-09-12T09:00:00.000Z'
)
on conflict (slug) do nothing;

insert into public.advice_guides (slug, title, summary, category, content, featured_rank, related_slugs, author_name, reviewed_on, published_at)
values (
  'the-main-graduate-assessments-explained', 'The main graduate assessments, and how to prepare for each', 'Situational judgement, numerical and verbal tests, critical thinking, video interviews, coding tests, case interviews and assessment centres.', 'assessments',
  $json$[{"type":"paragraph","text":"Employers use different assessments to compare many applicants fairly. The names vary, and tests from different providers look different, so treat this as a map of the common types rather than a description of any one employer's process. Where an employer publishes its stages, plan around those."},{"type":"heading","level":2,"id":"aptitude-tests","text":"Aptitude tests"},{"type":"list","items":["Numerical reasoning: answering questions from tables and charts — percentages, ratios and changes over time — under time pressure.","Verbal reasoning: reading a passage and judging whether statements are true, false, or cannot be determined from what is written.","Critical thinking: judging inferences, assumptions and arguments. The key habit is to use only the information given, not what you already know.","Logical or diagrammatic reasoning: spotting the pattern in a series of shapes or figures."]},{"type":"heading","level":2,"id":"situational-judgement","text":"Situational judgement tests"},{"type":"paragraph","text":"You are given a workplace scenario and asked to rank or choose the most effective responses. There is rarely a trick: read the scenario carefully, think about what a thoughtful colleague would do, and pay attention to the employer's stated values."},{"type":"heading","level":2,"id":"interviews-and-exercises","text":"Interviews and exercises"},{"type":"list","items":["Video interviews: you record answers to set questions, often with a short preparation time. Practise speaking to a camera and keep to time.","Coding assessments: timed problems in a browser. Practise the fundamentals of the language you will be asked to use.","Case interviews: you work through a business problem aloud. Practise structuring a problem and explaining your reasoning as you go.","Assessment centres: a mix of exercises, group work, presentations and interviews, usually in one day."]},{"type":"heading","level":2,"id":"how-to-practise","text":"How to practise well"},{"type":"paragraph","text":"Practise each type until the format feels routine, then do some under real time limits. Review every mistake, not just the score — the pattern in what you get wrong tells you what to work on. JobPilot's Test Prep offers original practice in several of these formats; it does not reproduce any employer's or test provider's actual questions."}]$json$::jsonb,
  null, array['prepare-for-a-competency-interview', 'how-to-read-a-graduate-scheme-listing']::text[], 'JobPilot AI editorial team', '2026-09-15', '2026-09-15T09:00:00.000Z'
)
on conflict (slug) do nothing;

insert into public.advice_guides (slug, title, summary, category, content, featured_rank, related_slugs, author_name, reviewed_on, published_at)
values (
  'choosing-between-job-offers', 'Choosing between job offers: a simple framework', 'How to compare offers on what actually matters to you, and what to ask before you say yes.', 'career_advice',
  $json$[{"type":"paragraph","text":"A choice between offers feels like it should have a right answer. Usually it has a right answer for you, and the work is in working out what you value. A short, written comparison beats a gut feeling formed in the first excited hour."},{"type":"heading","level":2,"id":"decide-what-matters","text":"Decide what matters, in order"},{"type":"paragraph","text":"Before comparing anything, write down the four or five things that matter most to you — learning, pay, location, flexibility, the people, the employer's reputation, stability, visa support if you need it — and put them in order. Do this first, so the offers do not decide the list for you."},{"type":"heading","level":2,"id":"compare-like-for-like","text":"Compare like for like"},{"type":"list","items":["Total pay and how it is made up: salary, bonus, pension contribution, and anything you would otherwise pay for.","Progression: what the first two years actually look like, and how people typically move on.","The day-to-day: the team, the manager, the hours, and how much you would work from home.","Training and support, and what happens if it is not working out."]},{"type":"heading","level":2,"id":"ask-questions","text":"Ask what you still don't know"},{"type":"paragraph","text":"It is normal to ask questions after an offer, and employers expect it. Ask to speak to someone in the team, to see the written terms, and about anything that would change your decision. If you need sponsorship, confirm exactly what is offered and who pays for what, in writing."},{"type":"heading","level":2,"id":"give-yourself-time","text":"Take reasonable time, and be courteous"},{"type":"paragraph","text":"Ask how long you have to decide. If another process is still running, you can say so politely and ask whether the deadline can move. Whatever you decide, respond promptly and thank the employers you decline."}]$json$::jsonb,
  null, array['prepare-for-a-competency-interview', 'sponsorship-basics-what-a-licence-means']::text[], 'JobPilot AI editorial team', '2026-09-18', '2026-09-18T09:00:00.000Z'
)
on conflict (slug) do nothing;
